// n8n Code Node (Mode: "Run Once for All Items")

const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const output = [];

for (const item of $input.all()) {
  let rawData = item.json.output || item.json.text || item.json.response || item.json;

  // 1. If it's a string, strip markdown formatting and parse JSON
  if (typeof rawData === 'string') {
    try {
      const sanitized = rawData
        .replace(/```(?:json)?/gi, '')
        .replace(/```/g, '')
        .trim();
      rawData = JSON.parse(sanitized);
    } catch (err) {
      // If parsing fails, skip or keep raw error
      continue;
    }
  }

  // 2. Ensure we handle both single objects and arrays of objects
  const records = Array.isArray(rawData) ? rawData : [rawData];

  for (const record of records) {
    if (!record || typeof record !== 'object') continue;

    // --- Cleaning Logic ---

    // Clean Email: check format and filter out placeholders like "INVALID_EMAIL", "N/A", "null"
    const rawEmail = (record.Email || '').trim();
    const isPlaceholder = ['INVALID_EMAIL', 'N/A', 'NONE', 'NULL', 'UNDEFINED'].includes(rawEmail.toUpperCase());
    const validEmail = !isPlaceholder && emailRegex.test(rawEmail) ? rawEmail.toLowerCase() : null;

    // Clean Phone: normalize non-numeric characters and handle 10-digit formats
    const rawPhone = String(record.Phone || '').replace(/\D/g, '');
    const validPhone = rawPhone.length >= 10 ? rawPhone.slice(-10) : null;

    // Clean Name & Course: trim extra whitespace
    const cleanName = (record.Name || '').trim();
    const cleanCourse = (record.Course || '').trim();
    const cleanCity = (record.City || '').trim();

    // Clean Fee_Paid: normalize boolean / string values
    const feePaid = record.Fee_Paid === true || String(record.Fee_Paid).toLowerCase() === 'true';

    // Clean Date: validate ISO format (YYYY-MM-DD)
    const rawDate = (record.Enrolled_Date || '').trim();
    const enrolledDate = !isNaN(Date.parse(rawDate)) ? new Date(rawDate).toISOString().split('T')[0] : null;

    output.push({
      json: {
        studentId: record.Student_ID || null,
        name: cleanName || null,
        email: validEmail,
        phone: validPhone,
        course: cleanCourse || null,
        feePaid: feePaid,
        city: cleanCity || null,
        enrolledDate: enrolledDate,
        isValidRecord: Boolean(cleanName && (validEmail || validPhone)) // flag records missing vital contact info
      }
    });
  }
}

return output;
